from pathlib import Path
from collections import Counter, defaultdict
import json
S={p.name.split('.')[-2]:p.read_text().splitlines()[1::4] for p in Path('.').glob('*.fq')}
def rc(s):return s.translate(str.maketrans('ACGTN','TGCAN'))[::-1]
k=25
C=Counter()
for ss in S.values():
 for s in ss:
  for seq in [s,rc(s)]: C.update(seq[i:i+k] for i in range(len(seq)-k+1))
edges={s for s,n in C.items() if n>=3}
out=defaultdict(list); inc=defaultdict(list)
for s in edges:out[s[:-1]].append(s);inc[s[1:]].append(s)
visited=set();contigs=[]
for s in sorted(edges,key=lambda s:len(inc[s[:-1]])==len(out[s[:-1]])==1):
 if s in visited:continue
 seq=s;visited.add(s)
 while len(out[seq[-k+1:]])==1 and len(inc[seq[-k+1:]])==1:
  nxt=out[seq[-k+1:]][0]
  if nxt in visited:break
  seq+=nxt[-1];visited.add(nxt)
 if len(seq)>50 and rc(seq) not in contigs:contigs.append(seq)
contigs.sort(key=len,reverse=True)
print('contig lengths',list(map(len,contigs)))
Path('contigs.fa').write_text(''.join(f'>c{i}\\n{s}\\n' for i,s in enumerate(contigs)))
for i,c in enumerate(contigs):
 print('contig',i,len(c))
 for n,ss in S.items():
  pos=[]; unmatched=0
  for s in ss:
   hits=[]
   for seq in [s,rc(s)]:
    for j in range(0,len(s)-k+1,5):
     p=c.find(seq[j:j+k])
     if p>=0:hits.append(p-j)
   if hits:pos.append(Counter(hits).most_common(1)[0][0])
  counts=Counter(p//200 for p in pos)
  print(n,len(pos),sorted(counts.items()))
